body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

h2 {
  font-size: 15px;
  font-family: ui-monospace, "Cascadia Mono", monospace;
  margin: 0 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.call {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.call.ok { border-left-color: #0a7a35; }
.call.bad { border-left-color: #b91c1c; }

.status {
  display: inline-block;
  min-width: 40px;
  text-align: center;
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  background-color: #71717a;
}

.s-2xx { background-color: #0a7a35; }
.s-4xx { background-color: #b45309; }
.s-5xx { background-color: #b91c1c; }
.s-err { background-color: #b91c1c; }

pre {
  background-color: #f4f4f5;
  border-radius: 8px;
  padding: 10px 12px;
  margin: 0 0 8px;
  overflow-x: auto;
  font-size: 13px;
  white-space: pre-wrap;
}

pre:last-child { margin-bottom: 0; }

// Орчны хувьсагчаас тохиргоо унших.
// Дутуу зүйлийг ХҮСЭЛТИЙН үед биш, ЭХЛЭХЭД нь илрүүлэх нь чухал —
// эс бол алдаа хэрэглэгчийн өмнө, шөнө дунд гарна.

const REQUIRED = ["SITE_NAME","APP_VERSION","SESSION_TTL_HOURS"];

function loadConfig(env) {
  const missing = REQUIRED.filter((key) => !env[key]);

  if (missing.length > 0) {
    throw new Error("Орчны хувьсагч дутуу байна: " + missing.join(", "));
  }

  return Object.freeze({
    siteName: env.SITE_NAME,
    version: env.APP_VERSION,
    sessionTtlHours: Number(env.SESSION_TTL_HOURS),
  });
}

// Shop.mn-ий сервер — liveness ба readiness-ийг ялгах.

function json(body, status) {
  return new Response(JSON.stringify(body), {
    status: status || 200,
    headers: { "Content-Type": "application/json" },
  });
}

// Хамаарал (өгөгдлийн сан) бэлэн эсэхийг шалгаж,
// энэ replica урсгал хүлээж авахад бэлэн эсэхийг шийднэ.
function checkReady() {
  // энд бичнэ үү
}

async function handleRequest(request) {
  const path = new URL(request.url).pathname;

  // Liveness: процесс амьд эсэх. Хамаарлаас үл хамааран амьд бол 200.
  if (path === "/health" && request.method === "GET") {
    return json({ status: "ok", version: config.version });
  }

  // Readiness: урсгал хүлээж авахад бэлэн эсэх.
  if (path === "/ready" && request.method === "GET") {
    return checkReady();
  }

  if (path === "/api/products" && request.method === "GET") {
    return json(db.products);
  }

  return json({ error: "Хаяг олдсонгүй: " + path }, 404);
}

window.handleRequest = handleRequest;

// «Deploy турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
// Жинхэнэ сервер дээр эдгээр утга нь process.env-ээс ирнэ.

const db = {
  products: [
    { id: 1, name: "Монгол дээл", price: 129000 },
    { id: 2, name: "Малгай", price: 45000 },
  ],
};

// Серверийн код үүнийг глобалаар уншина.
window.db = db;

// Симуляц хийсэн хамаарал: өгөгдлийн сангийн холболт бэлэн эсэх.
// Жинхэнэ сервер дээр энэ нь идэвхтэй холболт шалгасны үр дүн байна.
const deps = { dbReady: true };
window.deps = deps;

const FULL_ENV = {
  SITE_NAME: "Shop.mn",
  APP_VERSION: "1.4.0",
  SESSION_TTL_HOURS: "24",
};

const SCENARIOS = [
  {
    "key": "ready_up",
    "method": "GET",
    "path": "/ready",
    "dbReady": true
  },
  {
    "key": "ready_down",
    "method": "GET",
    "path": "/ready",
    "dbReady": false
  },
  {
    "key": "health",
    "method": "GET",
    "path": "/health"
  }
];

const output = document.getElementById("output");

function panel(className, testid, title, lines) {
  const box = document.createElement("section");
  box.className = className;
  box.dataset.testid = testid;

  const heading = document.createElement("h2");
  heading.textContent = title;
  box.append(heading);

  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }

  output.append(box);
  return box;
}

window.CONFIG_OK = null;
window.CONFIG_BOOT_ERROR = null;

try {
  window.CONFIG_OK = loadConfig(FULL_ENV);
  panel("call ok", "config-ok", "Тохиргоо ачаалагдлаа", [JSON.stringify(window.CONFIG_OK, null, 2)]);
} catch (problem) {
  window.CONFIG_BOOT_ERROR = problem.message;
  panel("call bad", "config-boot-error", "Тохиргоо ачаалагдсангүй", [problem.message]);
}

// Серверийн код энэ тохиргоог глобалаар ашиглана.
const config = window.CONFIG_OK;
window.config = config;

(async function () {
  window.RESULTS = {};

  if (!config || typeof handleRequest !== "function") {
    document.body.dataset.ready = "1";
    return;
  }

  for (const scenario of SCENARIOS) {
    if (scenario.dbReady !== undefined) {
      deps.dbReady = scenario.dbReady;
    }

    const init = { method: scenario.method, headers: {} };
    if (scenario.body !== undefined) {
      init.headers["Content-Type"] = "application/json";
      init.body = JSON.stringify(scenario.body);
    }

    let status = 0;
    let body = null;
    let headers = {};
    let error = null;

    try {
      const response = await handleRequest(new Request("https://shop.mn" + scenario.path, init));

      if (!(response instanceof Response)) {
        throw new Error("handleRequest нь Response биш зүйл буцаалаа");
      }

      status = response.status;
      headers = {};
      response.headers.forEach((value, key) => {
        headers[key.toLowerCase()] = value;
      });

      const text = await response.text();
      try {
        body = text ? JSON.parse(text) : null;
      } catch (problem) {
        body = text;
      }
    } catch (problem) {
      error = problem.message;
    }

    window.RESULTS[scenario.key] = { status, body, headers, error };

    const box = panel(
      "call",
      "call-" + scenario.key,
      scenario.method + " " + scenario.path,
      [
        error ? "АЛДАА: " + error : JSON.stringify(body, null, 2),
        Object.keys(headers).length ? "headers: " + JSON.stringify(headers, null, 2) : "headers: —",
      ],
    );

    const badge = document.createElement("span");
    badge.className = "status " + (error ? "s-err" : "s-" + String(status)[0] + "xx");
    badge.dataset.testid = "status-" + scenario.key;
    badge.textContent = error ? "алдаа" : String(status);
    box.querySelector("h2").prepend(badge, document.createTextNode(" "));
  }

  document.body.dataset.ready = "1";
})();

